/**
 * Declarative sidebar layout for the ARGVUS documentation site.
 *
 * This file holds only data: which slugs go where, in what order, with which
 * sidebar-only label overrides and PT-BR translations. The assembly logic
 * that turns this data (plus whatever pages actually loaded from each
 * project) into a Starlight sidebar config lives in `starlight-sidebar-config.ts`.
 *
 * Edit this file to reorder sections, add a page to an explicit position, or
 * recategorize a component. Never edit `generated-sidebar.mjs` directly: it is
 * build output, regenerated by `npm run generate:sidebar`.
 */

/** A single sidebar link, resolved against a loaded content entry's slug. */
export interface LayoutLinkSpec {
  slug: string
  /** Sidebar-only label override. Omit to use the page's own (localized) title. */
  label?: string
  /** PT-BR translation of `label`. Only meaningful when `label` is set. */
  translations?: Record<string, string>
}

/** A sidebar group of links and/or nested groups. */
export interface LayoutGroupSpec {
  group: string
  translations?: Record<string, string>
  collapsed?: boolean
  items: LayoutNodeSpec[]
}

export type LayoutNodeSpec = LayoutLinkSpec | LayoutGroupSpec

export function isLayoutGroup(node: LayoutNodeSpec): node is LayoutGroupSpec {
  return 'group' in node
}

