/**
 * Explicit ordering for a component's user-facing pages, keyed by the page's
 * path segment(s) relative to the project root (`docs/<repo>/<relPath>`;
 * `docs/<repo>` itself and anything under `developer-guide/` are handled
 * separately and never appear here). Docs are flattened post-migration, so
 * `relPath` is normally just the file name (e.g. `installation`), but the
 * lookup also tolerates a leading `user-guide/` segment for a project that
 * hasn't been migrated yet. Components not listed here fall back to
 * alphabetical order by slug. Any page that exists but isn't named in an
 * explicit list here is still appended (alphabetically, with a
 * `console.warn`), so nothing can silently disappear.
 */
export const COMPONENT_PAGE_ORDER: Record<string, string[]> = {
  'argvus-hyprland': ['keyboard-shortcuts', 'input', 'windows-and-layout', 'hyprland-overrides'],
  'argvus-appearance': ['wallpapers', 'fonts-and-icons', 'effects'],
  'argvus-themes': ['installing-themes', 'official-themes', 'highlight-color', 'import-and-export'],
  'argvus-session': ['graphical-session', 'tty-session'],
  'argvus-taskbar': ['taskbar', 'widgets'],
  'argvus-boot-splash': ['installation', 'usage', 'uki-splash', 'troubleshooting', 'reference', 'uninstallation'],
}

/** Boot Splash's `developer-guide/*` page order (relPath `''` = the `developer-guide` root page itself). */
export const BOOT_SPLASH_DEV_NOTES_ORDER: string[] = ['', 'theme', 'packaging', 'ci-releases', 'workflow']
